package com.davidblackcn.buildupmobtweaks;
import com.davidblackcn.buildupmobtweaks.villager.profession.*;
import net.fabricmc.api.ModInitializer;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.memory.*;
import net.minecraft.world.entity.npc.villager.*;
import net.minecraft.world.entity.animal.sheep.Sheep;
import net.minecraft.world.entity.animal.golem.IronGolem;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.projectile.FishingHook;
import net.minecraft.world.entity.projectile.throwableitemprojectile.ThrownSplashPotion;
import net.minecraft.world.item.*;
import net.minecraft.world.item.alchemy.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.HopperBlockEntity;
import com.mojang.serialization.MapCodec;
import java.util.*;
import static com.davidblackcn.buildupmobtweaks.FarmerIntelligenceTests.*;

public final class ProfessionResourceTests implements ModInitializer {
    static final String ENV="buildupmobtweaks:profession_resources";
    public record Settings(ProfessionCoreTests.Settings core,boolean daily,boolean heal,boolean feed,boolean wool){}
    public record Environment() implements TestEnvironmentDefinition<Settings>{
        static final MapCodec<Environment> CODEC=MapCodec.unit(Environment::new);
        public Settings setup(ServerLevel l){var old=new ProfessionCoreTests.Environment().setup(l);var c=BuildupMobTweaks.config().villagers.professions;var r=new Settings(old,c.daily_routines.get(),c.self_heal.get(),c.baby_feeding.get(),c.wool_pickup.get());c.daily_routines.accept(false);c.self_heal.accept(true);c.baby_feeding.accept(true);c.wool_pickup.accept(false);c.action_cooldown.accept(2400);return r;}
        public void teardown(ServerLevel l,Settings old){var c=BuildupMobTweaks.config().villagers.professions;c.daily_routines.accept(old.daily());c.self_heal.accept(old.heal());c.baby_feeding.accept(old.feed());c.wool_pickup.accept(old.wool());new ProfessionCoreTests.Environment().teardown(l,old.core());}
        public MapCodec<Environment> codec(){return CODEC;}
    }
    public void onInitialize(){Registry.register(BuiltInRegistries.TEST_ENVIRONMENT_DEFINITION_TYPE,BuildupMobTweaks.id("profession_resources_test"),Environment.CODEC);}
    static Villager worker(GameTestHelper h,ResourceKey<VillagerProfession> p,Block b){var v=ProfessionCoreTests.worker(h,p,b);v.setCanPickUpLoot(false);return v;}
    static int ops(Villager v){return ProfessionWorkState.peek(v).map(r->r.operations).orElse(0);}
    static void done(GameTestHelper h,Villager v,String scene){BuildupMobTweaks.LOGGER.info("A3_RESOURCE_PROOF scene={} operations={} inventory={} held={} data={}",scene,ops(v),v.getInventory().getItems(),v.getMainHandItem(),v.getAttached(ProfessionWorkState.DATA));v.discard();h.succeed();}
    static Sheep sheep(GameTestHelper h,boolean baby){var s=h.spawn(EntityTypes.SHEEP,new BlockPos(10,2,8));s.setNoAi(true);if(baby)s.setAge(-12000);return s;}
    static int wool(GameTestHelper h){return h.getLevel().getEntitiesOfClass(ItemEntity.class,h.absoluteAABB(new net.minecraft.world.phys.AABB(0,0,0,28,12,28)).inflate(1)).stream().filter(e->e.getItem().is(net.minecraft.tags.ItemTags.WOOL)).mapToInt(e->e.getItem().getCount()).sum();}
    static int fish(GameTestHelper h,Villager v){int count=0;for(var s:v.getInventory().getItems())if(s.is(net.minecraft.tags.ItemTags.FISHES))count+=s.getCount();return count+h.getLevel().getEntitiesOfClass(ItemEntity.class,h.absoluteAABB(new net.minecraft.world.phys.AABB(0,0,0,28,12,28))).stream().filter(e->e.getItem().is(net.minecraft.tags.ItemTags.FISHES)).mapToInt(e->e.getItem().getCount()).sum();}
    static Villager fisher(GameTestHelper h){var v=worker(h,VillagerProfession.FISHERMAN,Blocks.BARREL);v.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED).setBaseValue(.5);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.FISHING_ROD));for(int x=12;x<=17;x++)for(int z=5;z<=11;z++)h.setBlock(new BlockPos(x,1,z),Blocks.WATER);return v;}
    static Villager patient(GameTestHelper h){var v=h.spawn(EntityTypes.VILLAGER,new BlockPos(10,2,8));v.setNoAi(true);v.setHealth(8);return v;}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void mealConsumesOneRealBreadAndHealsWithoutEquippingCopy(GameTestHelper h){var v=worker(h,VillagerProfession.LIBRARIAN,Blocks.LECTERN);v.setHealth(14);v.getInventory().setItem(0,new ItemStack(Items.BREAD,1));h.runAtTickTime(600,()->{h.assertTrue(v.getHealth()==19&&v.getInventory().countItem(Items.BREAD)==0&&v.getMainHandItem().isEmpty()&&ops(v)==1,"One bread pays for native nutrition healing, real hand remains empty");done(h,v,"meal");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void tradeBeforeMealCommitKeepsTheOriginalFood(GameTestHelper h){var v=worker(h,VillagerProfession.LIBRARIAN,Blocks.LECTERN);v.setHealth(14);v.getInventory().setItem(0,new ItemStack(Items.BREAD,1));v.getOffers();var p=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);boolean[] interrupted={false};h.onEachTick(()->{if(!interrupted[0]&&ProfessionWorkState.busy(v)){interrupted[0]=true;v.setTradingPlayer(p);}});h.runAtTickTime(600,()->{h.assertTrue(interrupted[0]&&v.getHealth()==14&&v.getInventory().countItem(Items.BREAD)==1&&ops(v)==0,"Trade prevents uncommitted food debit/healing");v.setTradingPlayer(null);done(h,v,"meal_trade");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void shepherdActuallyShearsAndDamagesRealShearsOnce(GameTestHelper h){var v=worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var s=sheep(h,false);h.runAtTickTime(750,()->{h.assertTrue(s.isSheared()&&ops(v)==1&&v.getMainHandItem().getDamageValue()==1&&wool(h)>=1&&wool(h)<=3,"Native sheep shear state/drop and actual durability are conserved");done(h,v,"shear");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=650)
    public void noShearsNeverCreatesToolOrWool(GameTestHelper h){var v=worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);var s=sheep(h,false);h.runAtTickTime(550,()->{h.assertTrue(!s.isSheared()&&ops(v)==0&&wool(h)==0&&v.getMainHandItem().isEmpty(),"No free shears or sheep loot");done(h,v,"no_shears");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=650)
    public void babySheepIsNotSheared(GameTestHelper h){var v=worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var s=sheep(h,true);h.runAtTickTime(550,()->{h.assertTrue(!s.isSheared()&&ops(v)==0&&wool(h)==0&&v.getMainHandItem().getDamageValue()==0,"Immature sheep excluded");done(h,v,"baby_no_shear");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void ordinaryHoppersCollectOnlyTheNativeShearingDrops(GameTestHelper h){var v=worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));for(int x=9;x<=11;x++)for(int z=7;z<=9;z++)h.setBlock(new BlockPos(x,1,z),Blocks.HOPPER);var s=sheep(h,false);h.runAtTickTime(750,()->{int inHoppers=0;for(int x=9;x<=11;x++)for(int z=7;z<=9;z++)if(h.getLevel().getBlockEntity(h.absolutePos(new BlockPos(x,1,z))) instanceof HopperBlockEntity hopper)for(int i=0;i<hopper.getContainerSize();i++)if(hopper.getItem(i).is(net.minecraft.tags.ItemTags.WOOL))inHoppers+=hopper.getItem(i).getCount();h.assertTrue(s.isSheared()&&ops(v)==1&&inHoppers>=1&&inHoppers+wool(h)<=3&&v.getInventory().isEmpty(),"Native hopper consumes original wool entities, no second settlement");done(h,v,"native_hopper");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void protectionDenialKeepsSheepToolAndDropsUnchanged(GameTestHelper h){var v=worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.addTag("test_deny_all");v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var s=sheep(h,false);h.runAtTickTime(750,()->{h.assertTrue(!s.isSheared()&&ops(v)==0&&wool(h)==0&&v.getMainHandItem().getDamageValue()==0,"Shared interaction permission fails closed");done(h,v,"denied_shear");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void clericThrowsRealHealingPotionAndConsumesOnlyOne(GameTestHelper h){var v=worker(h,VillagerProfession.CLERIC,Blocks.BREWING_STAND);var target=patient(h);v.getInventory().setItem(0,PotionContents.createItemStack(Items.SPLASH_POTION,Potions.HEALING));boolean[] thrown={false};h.onEachTick(()->thrown[0]|=!h.getLevel().getEntitiesOfClass(ThrownSplashPotion.class,v.getBoundingBox().inflate(8),e->e.getOwner()==v).isEmpty());h.runAtTickTime(850,()->{h.assertTrue(thrown[0]&&target.getHealth()>8&&v.getInventory().countItem(Items.SPLASH_POTION)==0&&ops(v)==1,"Actual projectile heals the intended patient using one actual potion");done(h,v,"cleric_heal");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void harmingPotionCannotBecomeFriendlyMedicine(GameTestHelper h){var v=worker(h,VillagerProfession.CLERIC,Blocks.BREWING_STAND);var t=patient(h);v.getInventory().setItem(0,PotionContents.createItemStack(Items.SPLASH_POTION,Potions.HARMING));h.runAtTickTime(600,()->{h.assertTrue(t.getHealth()==8&&v.getInventory().countItem(Items.SPLASH_POTION)==1&&ops(v)==0,"Harming and custom effects rejected before resource transfer");done(h,v,"bad_medicine");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=1000)
    public void healingSplashDoesNotHealBystanderPlayerOrDamageNeutralUndead(GameTestHelper h){var v=worker(h,VillagerProfession.CLERIC,Blocks.BREWING_STAND);var t=patient(h);var z=h.spawn(EntityTypes.ZOMBIFIED_PIGLIN,new BlockPos(11,2,8));z.setNoAi(true);z.setHealth(10);z.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));var p=h.makeMockServerPlayerInLevel();p.snapTo(t.position().add(0,0,1));p.setHealth(10);p.getFoodData().setFoodLevel(10);p.getFoodData().setSaturation(0);h.setBlock(new BlockPos(11,4,8),Blocks.STONE);v.getInventory().setItem(0,PotionContents.createItemStack(Items.SPLASH_POTION,Potions.HEALING));h.runAtTickTime(900,()->{BuildupMobTweaks.LOGGER.info("A3_POTION_TARGETS patient={} player={} undead={} operations={} activities={}",t.getHealth(),p.getHealth(),z.getHealth(),ops(v),v.getBrain().getActiveActivities());h.assertTrue(t.getHealth()>8&&p.getHealth()==10&&z.getHealth()==10,"The projectile affects only its recorded living villager patient");z.discard();p.discard();done(h,v,"potion_bystanders");});}
    static void repair(GameTestHelper h,ResourceKey<VillagerProfession> profession,Block station){var v=worker(h,profession,station);v.getInventory().setItem(0,new ItemStack(Items.IRON_INGOT,1));var g=h.spawn(EntityTypes.IRON_GOLEM,new BlockPos(10,2,8));g.setNoAi(true);g.setHealth(40);h.runAtTickTime(750,()->{h.assertTrue(g.getHealth()==65&&v.getInventory().countItem(Items.IRON_INGOT)==0&&ops(v)==1,"Native iron-ingot repair amount is paid once from actual stock");done(h,v,"repair_"+profession.identifier());});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850) public void armorerRepairsWithActualIron(GameTestHelper h){repair(h,VillagerProfession.ARMORER,Blocks.BLAST_FURNACE);}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850) public void toolsmithUsesSharedRepairActivity(GameTestHelper h){repair(h,VillagerProfession.TOOLSMITH,Blocks.SMITHING_TABLE);}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850) public void weaponsmithUsesSharedRepairActivity(GameTestHelper h){repair(h,VillagerProfession.WEAPONSMITH,Blocks.GRINDSTONE);}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void missingIronDoesNotCreateFreeGolemRepairs(GameTestHelper h){var v=worker(h,VillagerProfession.ARMORER,Blocks.BLAST_FURNACE);var g=h.spawn(EntityTypes.IRON_GOLEM,new BlockPos(10,2,8));g.setNoAi(true);g.setHealth(40);h.runAtTickTime(600,()->{h.assertTrue(g.getHealth()==40&&ops(v)==0&&v.getInventory().isEmpty(),"No resource means no repair");done(h,v,"no_iron");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void optionalFarmerFeedingAcceleratesOnlyBabyUsingRealFood(GameTestHelper h){var v=worker(h,VillagerProfession.FARMER,Blocks.COMPOSTER);v.getInventory().setItem(0,new ItemStack(Items.WHEAT,1));var s=sheep(h,true);h.runAtTickTime(750,()->{h.assertTrue(s.isBaby()&&s.getAge()>-11000&&!s.isInLove()&&v.getInventory().countItem(Items.WHEAT)==0&&ops(v)==1&&harvests(v)==0,"One real wheat accelerates baby age without breeding or a second crop controller");done(h,v,"feed_baby");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void farmerDoesNotFeedAdultIntoBreedingMode(GameTestHelper h){var v=worker(h,VillagerProfession.FARMER,Blocks.COMPOSTER);v.getInventory().setItem(0,new ItemStack(Items.WHEAT,1));var s=sheep(h,false);h.runAtTickTime(600,()->{h.assertTrue(!s.isInLove()&&v.getInventory().countItem(Items.WHEAT)==1&&ops(v)==0,"Adult breeding is outside this activity");done(h,v,"adult_no_feed");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=1750)
    public void fishermanPhysicallyCastsAndRetrievesOneNativeFishLoot(GameTestHelper h){var v=fisher(h);boolean[] flying={false},wet={false};h.onEachTick(()->{for(var hook:h.getLevel().getEntitiesOfClass(FishingHook.class,v.getBoundingBox().inflate(12),e->e.getOwner()==v)){flying[0]=true;wet[0]|=hook.isInWater();}});h.runAtTickTime(1600,()->{BuildupMobTweaks.LOGGER.info("A3_FISH_OBSERVATION cast={} wet={} fish={} operations={} pos={} held={}",flying[0],wet[0],fish(h,v),ops(v),v.position(),v.getMainHandItem());h.assertTrue(flying[0]&&wet[0]&&fish(h,v)==1&&ops(v)==1&&v.getMainHandItem().getDamageValue()==1,"Actual bobber reaches water, native bite produces one fish and one durability debit");done(h,v,"fish");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void waterRemovalCancelsCastWithoutFreeFish(GameTestHelper h){var v=fisher(h);boolean[] changed={false};h.onEachTick(()->{if(!changed[0]&&!h.getLevel().getEntitiesOfClass(FishingHook.class,v.getBoundingBox().inflate(12),e->e.getOwner()==v).isEmpty()){changed[0]=true;for(int x=12;x<=17;x++)for(int z=5;z<=11;z++)h.setBlock(new BlockPos(x,1,z),Blocks.STONE);}});h.runAtTickTime(850,()->{h.assertTrue(changed[0]&&ops(v)==0&&fish(h,v)==0&&v.getMainHandItem().getDamageValue()==0&&h.getLevel().getEntitiesOfClass(FishingHook.class,v.getBoundingBox().inflate(12),e->e.getOwner()==v).isEmpty(),"Removed water cancels actual hook and no resource payout is replayed");done(h,v,"fish_water_removed");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=1100)
    public void activeFishingSerializeReloadDiscardsOldHookAndKeepsCooldown(GameTestHelper h){Villager[] ref={fisher(h)};boolean[] loaded={false};net.minecraft.nbt.CompoundTag[] raw={null};FishingHook[] old={null};h.onEachTick(()->{if(!loaded[0]){var hooks=h.getLevel().getEntitiesOfClass(FishingHook.class,ref[0].getBoundingBox().inflate(12),e->e.getOwner()==ref[0]);if(!hooks.isEmpty()){old[0]=hooks.getFirst();raw[0]=ref[0].getAttached(ProfessionWorkState.DATA).copy();ref[0]=CombatTestWorld.reload(h,ref[0]);loaded[0]=true;}}});h.runAtTickTime(1000,()->{h.assertTrue(loaded[0]&&old[0].isRemoved()&&raw[0].equals(ref[0].getAttached(ProfessionWorkState.DATA))&&fish(h,ref[0])==0&&ops(ref[0])==0&&ref[0].getMainHandItem().getDamageValue()==0,"Native reload keeps original rod/cooldown and never resumes a half-finished payout");done(h,ref[0],"fish_reload");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void noAiInterruptsShearingBeforeResourceCommit(GameTestHelper h){var v=worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var s=sheep(h,false);boolean[] interrupted={false};h.onEachTick(()->{if(!interrupted[0]&&ProfessionWorkState.busy(v)){interrupted[0]=true;v.setNoAi(true);}});h.runAtTickTime(750,()->{h.assertTrue(interrupted[0]&&!s.isSheared()&&wool(h)==0&&ops(v)==0&&!ProfessionWorkState.busy(v),"Actual active work exits at the tick boundary before world modification");done(h,v,"shear_noai");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void externalFarmerTakeoverDuringFeedingKeepsOriginalFoodAndAge(GameTestHelper h){var v=worker(h,VillagerProfession.FARMER,Blocks.COMPOSTER);v.getInventory().setItem(0,new ItemStack(Items.WHEAT));var baby=sheep(h,true);boolean[] changed={false};h.onEachTick(()->{if(!changed[0]&&ProfessionWorkState.busy(v)){changed[0]=true;v.addTag("buildupmobtweaks:farmer_external");}});h.runAtTickTime(750,()->{h.assertTrue(changed[0]&&ops(v)==0&&v.getInventory().countItem(Items.WHEAT)==1&&baby.getAge()<=-11200&&!ProfessionWorkState.busy(v),"External Farmer controller takes over before food debit or age acceleration");done(h,v,"feed_external_takeover");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=1750)
    public void fishermanOnWorkstationTopFindsWaterAndWalksToTheBank(GameTestHelper h){var v=fisher(h);var top=p(h,8,8).above();v.snapTo(top.getX()+.5,top.getY(),top.getZ()+.5,0,0);boolean[] cast={false};h.onEachTick(()->cast[0]|=!h.getLevel().getEntitiesOfClass(FishingHook.class,v.getBoundingBox().inflate(12),e->e.getOwner()==v).isEmpty());h.runAtTickTime(1600,()->{h.assertTrue(cast[0]&&fish(h,v)==1&&ops(v)==1&&v.getMainHandItem().getDamageValue()==1,"Real Brain recovers from standing on its barrel, walks to a bank and catches once");done(h,v,"fish_from_barrel_top");});}
}